const vulnImageVerdict = `-- name: VulnImageVerdict :one
SELECT COALESCE(blk.id::text, '')::text AS finding_id, COALESCE(blk.advisory_id, '')::text AS advisory_id,
       COALESCE(blk.kind, '')::text AS kind, COALESCE(blk.status, '')::text AS status, COALESCE(s.state, '')::text AS scan_state,
       (s.db_digest IS NOT NULL)::boolean AS detected, COALESCE(s.error_code, '')::text AS error_code, COALESCE(s.judged, '')::text AS judged,
       (m.digest IS NULL
        OR (m.media_type IN ('application/vnd.oci.image.manifest.v1+json', 'application/vnd.docker.distribution.manifest.v2+json')
            AND COALESCE(m.artifact_type, '') IN ('', 'application/vnd.oci.image.config.v1+json', 'application/vnd.docker.container.image.v1+json')
            AND m.subject IS NULL AND NOT m.attachment
            AND NOT EXISTS (SELECT 1 FROM signatures g JOIN signature_attachments a ON a.signature_id = g.id
                             WHERE g.object_sha256 = m.digest AND a.repo_id = m.repo_id)))::boolean AS image
  FROM (SELECT 1) AS one
  LEFT JOIN vuln_image_scan s ON s.repo_id = $1::bigint AND s.name = $2::text AND s.digest = $3
  LEFT JOIN oci_manifests m ON m.repo_id = $1::bigint AND m.name = $2::text AND m.digest = $3
  LEFT JOIN LATERAL (
        SELECT f.id, f.advisory_id, f.kind, f.status
          FROM vuln_finding f
         WHERE f.repo_id = $1::bigint AND f.ecosystem = 'OCI' AND f.package_name = $2::text
           AND f.version = $4::text
           AND f.status IN ('needs_triage', 'confirmed', 'blocked')
           AND (f.status = 'blocked' OR (f.kind = 'malicious' AND $5::boolean))
         ORDER BY (f.kind = 'malicious' AND $5::boolean) DESC, f.severity_rank DESC, f.advisory_id
         LIMIT 1) AS blk ON true
`

type VulnImageVerdictParams struct {
	RepoID         int64
	Name           string
	Digest         []byte
	Version        string
	BlockMalicious bool
}

type VulnImageVerdictRow struct {
	FindingID  string
	AdvisoryID string
	Kind       string
	Status     string
	ScanState  string
	Detected   bool
	ErrorCode  string
	Judged     string
	Image      bool
}

// What a pull of a manifest needs to know (R-VULN-015): the finding that blocks the manifest in the repository, if any, how far the
// manifest has been scanned, and whether it is an image to scan at all. image is VulnImageDiscover's selection of the manifest's row: an
// index, an attachment (Docker's attestation manifest), a referrer, a signature and an artifact that is no container image are no image
// and are never scanned, so the missing-data rule does not hold them (Q-VULN-271); the platform image a client fetches next is gated on its
// own. A manifest the repository holds no row of (a remote's miss by digest, before its fetch) counts as an image: what it is is not known
// yet. error_code and judged say why a scan failed and whether it is tried again, for the text of the refusal. One statement, the
// finding's unique index and the keys of the scan row and of the manifest row.
func (q *Queries) VulnImageVerdict(ctx context.Context, arg VulnImageVerdictParams) (VulnImageVerdictRow, error) {
	row := q.db.QueryRow(ctx, vulnImageVerdict,
		arg.RepoID,
		arg.Name,
		arg.Digest,
		arg.Version,
		arg.BlockMalicious,
	)
	var i VulnImageVerdictRow
	err := row.Scan(
		&i.FindingID,
		&i.AdvisoryID,
		&i.Kind,
		&i.Status,
		&i.ScanState,
		&i.Detected,
		&i.ErrorCode,
		&i.Judged,
		&i.Image,
	)
	return i, err
}
